#!/usr/bin/env python3
# =====================================================================
#  apply_fleet_monitor.py  —  fence FLEET_MONITOR_20261127   (on main f7672dcd, v12.0.21)
#  TD-110  Fleet Monitor, Phase 1
#
#  One read-only web portal where Anbu and invited friends see every install's
#  LIVE trades, critical alerts, daily summary and trade history, and the
#  droplet relays every install's criticals to Telegram (non-admin installs
#  have no bot of their own). No paid domain, no new hosting.
#
#  APP (every install):
#   backend/app/monitor/outbox.py     NEW  durable local queue, own SQLite file (never app.db)
#   backend/app/monitor/tap.py        NEW  LIVE-only, allowlisted payloads (no token / URL / button)
#   backend/app/monitor/snapshot.py   NEW  60 s LIVE picture from the Dashboard's own feed (fleet_today)
#   backend/app/monitor/shipper.py    NEW  HTTPS to 139.59.8.202 with SNI 139-59-8-202.sslip.io
#                                          (verified, no DNS needed), ack + resend, back-off, server pause
#   backend/app/api/telegram_api.py   one tap line in notify_trade_entry / tp / sl / manual exit,
#                                     group entry / exit, critical (PAPER stays home), order rejection,
#                                     system alert
#   backend/app/api_server.py         starts the ship loop under _supervise, next to the liveness ping
#   backend/app/monitor/test_monitor_ship.py  NEW  TC-MON-0001…0027
#  SERVER (license droplet, own service + DB; the license server is untouched):
#   monitor_server/server.py store.py auth.py pages.py relay.py users.py  NEW
#   monitor_server/Caddyfile scalp-monitor.service requirements.txt     NEW
#   monitor_server/deploy-monitor.command                               NEW  one-click deploy
#   monitor_server/test_monitor_server.py                               NEW  TC-MONSRV-0001…0027
#
#  Run ONLY this script:
#     cd ~/dev/scalp-app && python3 apply_fleet_monitor.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Rollout: 1) ./monitor_server/deploy-monitor.command  2) users.py add …  3) release the app.
#  An app released before the server is up just queues events and retries.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "FLEET_MONITOR_20261127"
ITEMS = json.loads(r'''[{"path": "backend/app/monitor/__init__.py", "orig": null, "new": "1262af31f9e96c0b0248e99b3ab8de350af4be3cd8837f9cf14e10e6bd6c9b24", "exec": false, "blob": ""}, {"path": "backend/app/monitor/outbox.py", "orig": null, "new": "09cf04de2e4e761a36f720a02bedb225859b1ef63b62284bb2186cb3dae5728b", "exec": false, "blob": ""}, {"path": "backend/app/monitor/tap.py", "orig": null, "new": "3af5cdffb76c0dcdeadc0dbdb0c8115467d5a3292eb738ae6931e53dec4bef28", "exec": false, "blob": ""}, {"path": "backend/app/monitor/snapshot.py", "orig": null, "new": "b74929a9e972ec5341ae003553a44607d10d15b24de26d90688fd06ca4967775", "exec": false, "blob": ""}, {"path": "backend/app/monitor/shipper.py", "orig": null, "new": "a44050a3ec2d87c47201874c6e5cec9bb3096b8f30dcc564756e87f70b3b1d86", "exec": false, "blob": ""}, {"path": "backend/app/monitor/test_monitor_ship.py", "orig": null, "new": "ca0f8db2da6a212d0c21cb2dd75513728850e8b1b19766d9274d9825db54dc4e", "exec": false, "blob": ""}, {"path": "backend/app/api/telegram_api.py", "orig": "9a9101a88e44aba7cd33203028641e67c958d5c9b7c5057f1d6e8d363bdfd7c9", "new": "10f2f3649204c6506c01d17ddc2ec035d86c5ae9ba5fffce0fd7298022fbc7ea", "exec": false, "blob": ""}, {"path": "backend/app/api_server.py", "orig": "fd20102c1167f5f3c45b7fa30540369bcd158b811c21861b4f15c066764a2718", "new": "e4a1939ddbab60f248ec4c47d56e6fec93315c22cb905dbf2509e35eb8bd71f8", "exec": false, "blob": ""}, {"path": "monitor_server/server.py", "orig": null, "new": "30952624f9bf6233188fe2731264e40005a808ec06706580094ab9b10401cff7", "exec": false, "blob": ""}, {"path": "monitor_server/store.py", "orig": null, "new": "b57199dad0ed4e1733479473c04a233e062cf2047a5d03378ad1f0d9e80a846b", "exec": false, "blob": ""}, {"path": "monitor_server/auth.py", "orig": null, "new": "fb304117cd7760788a12af71d404b2dfcdb80adfa2fd22549c2f3f3f4d81a8d7", "exec": false, "blob": ""}, {"path": "monitor_server/pages.py", "orig": null, "new": "59feba681d495819bad60a598f3aa306b9b2184596f73cb0abf802526504a6a1", "exec": false, "blob": ""}, {"path": "monitor_server/relay.py", "orig": null, "new": "79f7686bb80f90434f4ff1848808883330b1ad60715dad4b3d42f768267614ec", "exec": false, "blob": ""}, {"path": "monitor_server/users.py", "orig": null, "new": "116c76fc2d5fa751eb0e673195736d1a1e456a43bc6dbfbf0c26e05ec62cab13", "exec": true, "blob": ""}, {"path": "monitor_server/requirements.txt", "orig": null, "new": "b819eb0fee04db25c3a3bcdc809194d756af61a5faa82f6dee90823b49c16494", "exec": false, "blob": "eNpLSywuSSzItLM10DM0NNCxMdQz4Coty0zOL8oDiRlZQoQA6ZgKoA=="}, {"path": "monitor_server/scalp-monitor.service", "orig": null, "new": "16323c4de9ea245cd88114417356acd8f4cd7d47e99e10b9af623f34cba54268", "exec": false, "blob": ""}, {"path": "monitor_server/Caddyfile", "orig": null, "new": "d216a0a39f91c5084ca67b8920612c7d2010339759cd42444e6f169ef5a3006c", "exec": false, "blob": ""}, {"path": "monitor_server/deploy-monitor.command", "orig": null, "new": "5ef07164480ff3a89fa7ef801c2aa6d1de95f8f7baba45d9382b55e4522c1c86", "exec": true, "blob": ""}, {"path": "monitor_server/test_monitor_server.py", "orig": null, "new": "97df23b2936e19434e4e93f9beb99905f8dfe58c3ed9b080ac235d730a20eb11", "exec": false, "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = [["backend", "app/monitor/test_monitor_ship.py"], ["root", "monitor_server/test_monitor_server.py"],
         ["backend", "app/jobs/test_tg_summary_all_modes.py"], ["backend", "app/jobs/test_tg_personal_alerts.py"]]   # [where, path]: 'backend' = run from backend/, 'root' = from the repo root


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── parent fences: the code this patches ─────────────────────────────
PARENTS = {"backend/app/api/telegram_api.py": ["CRITICAL_ALERT_ROUTING_20260909", "TG_PERSONAL_ALERTS_20261027",
                                              "KITE_LOGIN_NUDGE_20261027", "CLOSE_MSG_FIX_20261029"],
           "backend/app/api_server.py": ["liveness_ping_loop", "ACC2_TASKGUARD"]}
if "--rollback" not in args:
    for _rel, _fs in PARENTS.items():
        _pf = os.path.join(repo, _rel)
        _txt = open(_pf, encoding="utf-8").read() if os.path.exists(_pf) else ""
        _miss = [f for f in _fs if f not in _txt]
        if _miss:
            die(f"{_rel} lacks {', '.join(_miss)} — pull the latest main first")


def refresh_master():
    """MASTER_SUITE.md and REPO_MAP.md follow the suites on disk (a new uitest file)."""
    for gen, a_, name in (("scripts/regression/master_suite.py", ["refresh"], "MASTER_SUITE.md"),
                          ("scripts/gen_repo_map.py", [], "REPO_MAP.md")):
        g = os.path.join(repo, gen)
        if not os.path.exists(g):
            continue
        r = subprocess.run([sys.executable, g] + a_, cwd=repo, capture_output=True, text=True, timeout=300)
        msg = ((r.stdout or "") + (r.stderr or "")).strip().splitlines()
        say("  " + (msg[-1] if msg else f"{name} refreshed") if r.returncode == 0
            else f"  !! {name} refresh failed — pre-commit will refresh it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.join(repo, b)):        # the build tree exists: new folders too
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it, p, build in targets():
        if build or not os.path.exists(p) or not os.path.exists(p + ".bak-" + FENCE):
            continue
        with open(p, "rb") as f:
            if sha(f.read()) != it["new"]:
                later.append(os.path.relpath(p, repo))
    if later:
        die("cannot roll back — changed again after this script (by a later fix or a local edit): "
            + ", ".join(later) + ". Roll the later fixes back first, newest first. Nothing was changed.")
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    refresh_master()
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped, later = [], 0, [], []
_applied = False                         # this script's marker is in the tree → it was applied
for it, p, build in targets():
    if not build and os.path.exists(p):
        with open(p, "rb") as f:
            if FENCE.encode() in f.read():
                _applied = True
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    if _applied:
        later.append(rel)                # applied, then changed by a later fix
        continue
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}"
        + (f"; {len(later)} changed again by later fixes" if later else "") + ") — nothing to do")
    sys.exit(0)
if later:
    die("partly applied: " + ", ".join(later) + " changed after this script while other files are "
        "not patched — check the tree (git status) before going on. Nothing was changed.")

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        # a planned file was just proven byte-identical to its expected base (sha == orig): only other drift stops us.
        _ok = {os.path.relpath(p, repo) for it, p, _c, b in plan if not b and it["orig"] is not None}
        dirty = [l for l in dirty if l[3:].strip() not in _ok]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="fleet_monitor_")
blobs = {}
for it in ITEMS:
    if it["new"] is None:                # a deletion: nothing to decode
        continue
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, it["path"].replace("/", "_"))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            bak = p + ".bak-" + FENCE
            if old is None:
                os.remove(p)
            elif os.path.exists(bak):
                shutil.copy2(bak, p)                 # bytes + mode back (also for a deleted file)
            else:
                open(p, "wb").write(old)
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        _mode = os.stat(p).st_mode if cur is not None else None
        if cur is not None:
            shutil.copy2(p, p + ".bak-" + FENCE)            # keeps the mode for --rollback
        if it["new"] is None:                # a deletion: backed up above, then removed
            os.remove(p)
            written.append((p, cur))
            say(f"  deleted {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
            continue
        t = p + ".tmp-" + FENCE
        os.makedirs(os.path.dirname(p), exist_ok=True)   # a new file may need a new folder
        open(t, "wb").write(blobs[it["path"]])
        if _mode is not None:
            os.chmod(t, _mode)
        os.replace(t, p)
        if it.get("exec"):
            os.chmod(p, 0o755)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")
refresh_master()

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for where, t in TESTS:
        cwd = backend if where == "backend" else repo
        if not os.path.exists(os.path.join(cwd, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=cwd, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        # the project venv can lag requirements.txt (PyJWT): retry such a suite with this Python
        if (r is not None and r.returncode != 0 and "ModuleNotFoundError" in outp
                and "No module named 'app" not in outp and os.path.abspath(sys.executable) != os.path.abspath(py)):
            try:
                r = subprocess.run([sys.executable, t], cwd=cwd, env=env, capture_output=True, text=True, timeout=900)
                outp = (r.stdout or "") + (r.stderr or "")
            except subprocess.TimeoutExpired:
                r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        refresh_master()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

# ── 5b. JSX parse gate (esbuild from frontend/node_modules, if installed) ──
_esb = os.path.join(repo, "frontend", "node_modules", ".bin", "esbuild")
if os.path.exists(_esb) and "--skip-tests" not in args:
    bad = []
    for it in ITEMS:
        if it["new"] is not None and it["path"].startswith("frontend/src/") and it["path"].endswith((".jsx", ".js")):
            r = subprocess.run([_esb, os.path.join(repo, it["path"]), "--loader:.js=jsx", "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(it["path"] + ": " + (r.stderr or "").strip()[:300])
    if bad:
        restore()
        refresh_master()
        die("JSX does not parse — every file restored:\n  " + "\n  ".join(bad))
    say("  ✓ esbuild parsed the changed frontend files")
else:
    say("  (esbuild not installed — the build will compile the frontend)")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)).")
say("  Next: 1) commit;  2) deploy the server once: ./monitor_server/deploy-monitor.command")
say("        3) add logins on the droplet (users.py);  4) release the app (./desktop/deploy-scalp.command).")
say("  Undo: python3 apply_fleet_monitor.py --rollback")
